    "source": "FURB 2024 — Pref. Brusque/SC (Prova Oficial)",
    "excerpt": "Leia o texto para responder às questões a seguir:\n\nONU DIVULGA VERSÃO PRELIMINAR DO TRATADO GLOBAL DE PLÁSTICOS\n\nA Organização das Nações Unidas (ONU) divulgou a versão preliminar (zero draft) do Tratado Global de Plásticos, que servirá de base para as negociações que ocorrerão no Comitê de Negociação Intergovernamental (INC) em Nairóbi, no Quênia. O documento apresenta metas e ações essenciais para enfrentar a crise planetária da poluição plástica, que afeta os oceanos, a biodiversidade e a saúde humana em escala global.\n\nPara Graham Forbes, líder da campanha global de plásticos do Greenpeace EUA, o documento traz avanços significativos, mas ainda precisa ser aprofundado: \"O rascunho inicial do tratado contém diretrizes importantes para limitar a produção desenfreada de plástico e proteger o clima do planeta. No entanto, é fundamental que as metas incluam explicitamente o respeito aos direitos humanos e das comunidades mais vulneráveis, além de uma transição justa para modelos de reutilização e reabastecimento. A responsabilização da indústria que lucra com a poluição plástica também é essencial, com um apelo para que grandes marcas, varejistas e empresas de alimentos invistam em modelos de reutilização e reabastecimento\".\n\nO Greenpeace defende que o Tratado Global de Plásticos deve estabelecer uma meta ambiciosa de redução de pelo menos 75% na produção de plástico até 2040, de forma a limitar o aquecimento global em até 1,5°C e viabilizar uma transição para uma economia de baixo carbono. As negociações devem ser concluídas até o final de 2024, quando o texto final com força de lei internacional será aprovado pelos Estados-membros.",
    "text": "Analise a sintaxe do período a seguir, retirado de \"ONU divulga versão preliminar do Tratado Global de Plásticos\":\n\n\"A responsabilização da indústria que lucra com a poluição plástica também é essencial, com um apelo para que grandes marcas, varejistas e empresas de alimentos invistam em modelos de reutilização e reabastecimento.\"\n\nAnalise as afirmações a seguir. Marque V, para verdadeiras, e F, para falsas:\n(__) O período pode ser classificado como composto por coordenação.\n(__) \"Grandes marcas, varejistas e empresas\" exerce a função de sujeito simples da oração principal.\n(__) \"Essencial\" exerce a função de predicativo do objeto.\n(__) O período apresenta uma conjunção subordinativa final.\n\nAssinale a alternativa que apresenta a sequência correta:",
    "options": [
      "F − F − F − V",
      "V − F − F − F",
      "V − F − V − F",
      "F − V − F − V",
      "V − V − V − F"
    ],
    "answer": 0,
    "explanation": "Gabarito Oficial FURB: Alternativa A (F - F - F - V).\n- 1ª afirmativa (F): O período é composto por subordinação (orações adjetiva e adverbial final).\n- 2ª afirmativa (F): É sujeito composto da oração subordinada adverbial final ('invistam').\n- 3ª afirmativa (F): 'Essencial' é predicativo do sujeito ('A responsabilização... é essencial').\n- 4ª afirmativa (V): 'para que' introduz oração subordinada adverbial final.",
