    "source": "FURB 2023 — Pref. Florianópolis/SC (Prova Oficial)",
    "text": "I. Ao analisar os números, o pedagogo e professor de educação física Marcos Neira... (terceiro parágrafo): a. cerca de 59,9% das docências do 6º ao 9º ano do ensino fundamental e de 67,6% daquelas oferecidas no ensino médio eram ministradas por professores qualificados na área do conhecimento. b. a média nacional mostra que 85% dos docentes de educação física são licenciados na disciplina, enquanto os percentuais equivalentes para sociologia e línguas estrangeiras são de 40% e 46%, respectivamente. II. Para reverter esse cenário, pesquisadores fazem apelo e defendem a urgência... (primeiro parágrafo): a. o número de concluintes de licenciaturas em áreas específicas passou de 123 mil em 2010 para 111 mil em 2021. b. o país vivencia um quadro de apagão de professores. III. Além disso, segundo o sociólogo, somente um terço dos estudantes que finalizam as licenciaturas vai atuar na docência... (último parágrafo): a. Licenciaturas de matemática em instituições públicas no formato presencial registraram 38% de vagas ociosas em 2021. b. muitas vagas, mesmo quando preenchidas, logo são abandonadas. IV. Ambas as pesquisas são realizadas anualmente... (último parágrafo): a. Censo da Educação Básica e Censo da Educação Superior. b. O estudo foi desenvolvido a partir do cruzamento de dados relativos a docentes. V. Esse conjunto de dados indica... (primeiro parágrafo): a. o número de concluintes de licenciaturas em áreas específicas passou de 123 mil em 2010 para 111 mil em 2021. b. em Pernambuco, por exemplo, apenas 32,4% das docências em física no ensino médio são ministradas por licenciados na disciplina, enquanto no Tocantins o valor equivalente para a área de sociologia é de 5,4%. Assinale a alternativa que apresenta a correta associação entre os termos:",
