    "source": "FURB 2023 — Pref. Florianópolis/SC (Prova Oficial)",
    "text": "Segundo uma pesquisa de Simielli (2023), a diferença entre a nota de um aluno negro e a de um branco no Pisa equivale a dois anos de escolaridade. Um levantamento elaborado pelo Todos Pela Educação e pela Mahin Consultoria Antirracista, com dados do Sistema de Avaliação da Educação Básica (Saeb), de 2019, demonstra essa disparidade. Em relação a uma criança negra, uma branca tem 18,9% mais chances de ter acesso à Educação Infantil do que uma criança negra; 39,2% mais chances de frequentar a escola; 40,4% mais chances de aprendizagem adequada em Língua Portuguesa e 53,9% mais chances de aprendizagem adequada em Matemática no 9° ano do Ensino Fundamental; e 48% mais chances de cursar o Ensino Superior (Gotti; Noronha, 2023). Dado esse contexto, registre V, para verdadeiras, e F, para falsas:",
