    "area": "Educação Infantil",
    "source": "FURB 2023 — Pref. Florianópolis/SC (Prova Oficial)",
    "text": "I. Ainda que a OMS chame a atenção acerca da lacuna na descoberta de tratamentos antibacterianos, o número de mortes relacionadas às superbactérias que resistem a medicamentos tradicionais permanece estável, principalmente nos últimos anos. II. Como as bactérias se tornam resistentes cada vez mais cedo, os medicamentos ficam obsoletos rapidamente e deixam de interessar à indústria farmacêutica. Além disso, o setor privado prefere investir em áreas mais lucrativas, como, por exemplo, a oncologia. III. O insuficiente número de pesquisas sobre novos antibióticos representa um sério desafio para superar a crescente pandemia de resistência antimicrobiana e deixa a população cada vez mais vulnerável a infecções bacterianas, incluindo as infecções mais simples. É correto o que se afirma em:",
    "excerpt": "A Organização Mundial de Saúde (OMS), em seu relatório 2021 Antibacterial agents in clinical and preclinical development: an overview and analysis, revelou que o desenvolvimento de novos tratamentos antibacterianos é inadequado para lidar com a crescente ameaça de resistência aos antibióticos. \"Há uma grande lacuna na descoberta de tratamentos antibacterianos e, mais ainda, na descoberta de tratamentos inovadores\", afirmou Hanan Balkhy, diretora-geral assistente da OMS sobre resistência antimicrobiana. No Brasil, o Sindicato da Indústria de Produtos Farmacêuticos (Sindusfarma) reforça a necessidade de investimento para frear o avanço das superbactérias (adaptado de Sobrinho (2023) e OPAS (2022)). Ao encontro dessa temática, analise as asserções a seguir:",
