    "area": "Língua Portuguesa",
    "source": "FURB 2023 — Pref. Florianópolis/SC (Prova Oficial)",
    "text": "I. É necessário manter as pessoas no centro do conjunto de soluções contra a insegurança alimentar e a má nutrição, particularmente no atual contexto de emergência climática. II. Ainda não se conseguiu melhorar de modo significativo os números anteriores à crise desencadeada pela pandemia de COVID-19. Com isso, se está, cada vez mais, distanciando-se do cumprimento da agenda 2050. III. É preciso promover ações que protejam as pessoas mais vulneráveis e transformem os sistemas alimentares por meio de políticas públicas holísticas para promover alimentação saudável e acessível. É correto o que se afirma em:",
    "excerpt": "De acordo com dados da Organização das Nações Unidas para a Alimentação e a Agricultura (FAO), da Organização Pan-Americana da Saúde, do Programa Mundial de Alimentos (WFP) e o Fundo das Nações Unidas para a Infância (UNICEF), na América Latina e no Caribe, a má nutrição infantil é um problema que, em suas diversas formas, continua afetando crianças e adolescentes. A desnutrição e o sobrepeso infantil são duas faces da mesma moeda e requerem uma abordagem abrangente. O excesso de peso infantil aumentou de forma alarmante nas últimas duas décadas, ameaçando a saúde e o bem-estar das crianças. Isso posto, analise as asserções a seguir:",
