    "source": "FURB 2023 — Pref. Florianópolis/SC (Prova Oficial)",
    "text": "Analise as afirmações a seguir sobre intencionalidade educativa e registre V, para verdadeiras, e F, para falsas: (__) A intencionalidade educativa se relaciona à ideia de que cabe ao profissional de educação, unicamente a partir das concepções de vida e educação que possui, determinar todas as etapas, experiências e aprendizagens a serem vividas pelas crianças no âmbito da educação infantil. (__) A intencionalidade educativa consiste na organização e proposição, pelo educador, de experiências que permitam às crianças conhecer a si e ao outro e de conhecer e compreender as relações com a natureza, com a cultura e com a produção científica, que se traduzem nas práticas de cuidados pessoais, nas brincadeiras, nas experimentações com materiais variados, na aproximação com a literatura e no encontro com as pessoas. (__) A intencionalidade educativa dialoga com o trabalho do educador, o qual inclui refletir, selecionar, organizar, planejar, mediar e monitorar o conjunto das práticas e interações, garantindo a pluralidade de situações que promovam o desenvolvimento pleno das crianças. (__) Uma prática pedagógica baseada na intencionalidade educativa enfraquece os princípios da democracia escolar e fortalece a percepção de que a Educação Infantil é guiada somente pelo olhar do educador, que planeja, realiza intervenções pedagógicas e as avalia. Assinale a alternativa que apresenta a sequência correta:",
