    "text": "Observando as palavras sublinhadas e sua numeração, identifique a qual delas corresponde à definição a seguir, adaptada de Almeida et al (2018): são as marcas, riscos, linhas, que se entrecruzam sem um sentido preestabelecido, feito por crianças, normalmente de dois a quatro anos de idade. [Revela] a falta de prontidão e domínio na representação da escrita, onde se caracteriza o movimento das mãos com marcas que não mostram signos de uma existência única. Podemos dizer que \"não é simplesmente uma atividade sensória motora descontextualizada, mas sim uma atividade [em] que através dos rabiscos pode-se perceber como a criança está se sentindo, o que ela quer comunicar; também atua diretamente nas habilidades de coordenação motora fina. É correto o que se afirma em:",
