    "text": "De acordo com o ensino fundamental de 9 anos, analise as proposições a seguir: I. A implantação de uma política de ampliação do ensino fundamental de oito para nove anos de duração exige tratamento político, administrativo e pedagógico, uma vez que o objetivo de um maior número de anos no ensino obrigatório é assegurar a todas as crianças um tempo mais longo de convívio escolar com maiores oportunidades de aprendizagem. II. A ampliação do ensino fundamental para nove anos significa, também, uma possibilidade de qualificação do ensino e da aprendizagem da alfabetização e do letramento, pois a criança terá mais tempo para se apropriar desses conteúdos. III. A aprendizagem não depende apenas do aumento do tempo de permanência na escola, mas também do emprego mais eficaz desse tempo: a associação de ambos pode contribuir significativamente para que os estudantes aprendam mais e de maneira mais prazerosa. É correto o que se afirma em:",
