    "text": "Com base nas características e pressupostos do ciclo de alfabetização, analise as proposições a seguir: I. O Ciclo da Alfabetização pressupõe um investimento nas crianças em suas pluralidades e a valorização dos seus diferentes saberes prévios e, consequentemente, requer um currículo que respeite sua diversidade e pluralidade culturais. II. Este currículo deve ser traduzido em planejamentos dinâmicos e interdisciplinares, elaborados coletivamente com estudantes e professores de todas as turmas do Ciclo da Alfabetização, de forma a assegurar a organicidade e o cumprimento das finalidades do processo. III. O ciclo de alfabetização, ao ser concebido como uma etapa escolar de três anos, favorece o estabelecimento de estratégias em que os conhecimentos sejam gradativamente apropriados, por meio de retomadas e aprofundamentos contínuos. É correto o que se afirma em:",
