    "source": "FURB 2023 — Pref. Ilhota/SC (Prova Oficial)",
    "text": "A respeito das responsabilidades e privilégio da docência na Educação Infantil, avalie as afirmativas a seguir: I. Deve-se acompanhar este momento de inserção das primeiras aprendizagens das crianças no coletivo, o que envolve considerar e aceitar as dificuldades vividas que cercam a experiência de aprender, os obstáculos que cada uma enfrenta em suas tentativas e esforços para ultrapassá-los e superá-los, os equívocos necessários e os inúteis, os medos e as alegrias espontâneos ante o espanto da novidade que é o desconhecido. II. A responsabilidade da Educação Infantil, e de seus profissionais, é muito grande, pois inclui garantir a saúde e a proteção física e, também, os direitos básicos de participação e liberdade de expressão. III. O professor não pode pensar ou movimentar-se pela criança, mas pode sustentar favorecer ou conter as ações e as experiências de cada uma no coletivo. É correto o que se afirma em:",
