    "text": "A instituição de ensino desempenha um papel fundamental como espaço de formação continuada e aperfeiçoamento profissional voltado para a qualificação da ação docente. Sobre esse tema, analise as afirmações a seguir: I. A formação continuada incentiva a reflexão sobre a prática docente e a aplicação de uma abordagem crítica à educação. II. Além das habilidades acadêmicas, a formação continuada pode incluir o desenvolvimento de habilidades socioemocionais. III. A formação continuada permite que os professores se atualizem em relação aos avanços nas disciplinas que ensinam e nas metodologias de ensino mais eficazes. IV. A formação continuada pode ser prejudicial ao desenvolvimento da aprendizagem, pois os professores estarão preocupados em se desenvolver profissionalmente e, com isso, deixarão de se ocupar em suas atividades docentes. É correto o que se afirma em:",
